    "text": "そうか。まあ、今言ってもしょうがないね。ううん。これからちらしをもう一度発注するわけにもいかないしね。こうなったら、アナログなやり方だけど、その部分だけ修正のシールを貼ろう。私が今からシールを作るから。",
